package dailyassignments;

public class Assignment15_NumberDoubles {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=1;
		int n=5;
		int doubles=2;//we can give like this or we can directly use this in print statement as 2.
		while(num<=n)
		{
			System.out.println(num+" -> "+num*doubles);
			num++;
		}
	}

}
